from app.services.screens import Screen

GUIDES = {
    'billing': ('Самостоятельное пополнение и ежедневная оплата', 'Клиент открывает Баланс → Пополнить, выбирает сумму либо вводит свою, затем оплачивает на странице ЮKassa. Средства зачисляются только после проверки платежа через API ЮKassa. Проверка выполняется кнопкой и автоматически раз в минуту. Повторная проверка не зачисляет деньги второй раз. Настройки магазина задаются в .env: YOOKASSA_SHOP_ID, YOOKASSA_SECRET_KEY, YOOKASSA_TEST_MODE. Секретный ключ не отправляйте в чаты. В тестовом режиме настоящие деньги не принимаются. Настройки чеков магазина необходимо проверить до приёма реальных платежей.\n\nПосле покупки в настройках автопродления конкретной подписки появляется Ежедневно · 5 ₽. Включение сохраняет уже оплаченный срок. После его окончания 5 ₽ списываются за 24 часа; месячное автопродление заменяется ежедневным. При недостатке денег доступ приостанавливается. После пополнения оплачиваются следующие 24 часа без списания за дни простоя. Замороженные, удалённые и передаваемые ключи исключены. Текущая блокировка относится к тестовым записям: реальное отключение требует серверной интеграции.'),
    'credit': ('Баланс и автопродление', 'Клиенты → карточка клиента → Пополнить баланс. Введите сумму и подтвердите после проверки оплаты или для выдачи бонуса. Повторное подтверждение не зачисляет сумму повторно. Автоматический приём оплаты картой ещё не подключён.\n\nКлиент оплачивает подписку с доступного баланса. В карточке каждой подписки отдельно включается автопродление на выбранный срок. По умолчанию оно выключено. Списание происходит по текущей цене с учётом персональной скидки. При недостатке денег отправляется уведомление без списания; после пополнения проверка повторится. Замороженные, удалённые и передаваемые ключи исключены. Сейчас ключи тестовые. Операции с балансом учитываются отдельно от поступлений платёжного провайдера.'),
    'gifts': ('Подарки подписок и ключей', 'После выпуска ключа клиент открывает его карточку → Подарить другому. Получателя можно выбрать в Telegram, ввести числовой ID или username клиента, уже известного боту. Перед подтверждением проверяется ID.\n\nПосле подтверждения подарок ждёт активации, даже если друг уже зарегистрирован. Отправитель нажимает Отправить другу: Telegram готовит сообщение с приглашением и сроком. Отправитель выбирает чат и сам отправляет сообщение от своего аккаунта. Бот не отправляет сообщения от имени человека автоматически.\n\nДруг переходит по ссылке в бота. Забрать подарок может только заданный Telegram ID. Получателю создаётся новый ключ на оставшийся срок, старый отзывается. Пока подарок не получен, ключ зарезервирован, можно отменить подарок. Остаток срока не приостанавливается в ожидании.\n\nВ управлении ключом доступно удаление с подтверждением. Удаление не возвращает деньги и дни. Одна подписка предназначена для одного телефона. Сейчас операции меняют тестовые записи; реальное отключение и ограничение устройств требуют подключения сервера.'),
    'support': ('Техподдержка и темы', '1. Создайте закрытую супергруппу, включите «Темы», добавьте бота администратором с правом «Управление темами». Выполните /bind_support со своего аккаунта.\n2. Клиент пишет в «Помощь → Поддержка». Бот создаёт одну тему на клиента, имя и Telegram ID видны в заголовке. Последующие вопросы и новые тикеты используют ту же тему.\n3. Просто пишите внутри темы: текст, фото или файл уйдут именно этому клиенту. Отдельные карточки после каждого ответа не появляются; реакция 👍 означает, что ответ принят в очередь. При включённом Privacy Mode бот-администратор получает сообщения в теме.\n4. В начале темы одна панель с номером и статусом текущего тикета. /close или «Закрыть обращение» требует подтверждения. Тема закрывается после доставки оставшихся сообщений. Новый вопрос клиента создаёт новый тикет и открывает ту же тему.\n5. Не пишите ответы в «Общее»: там нет выбранного клиента. Команды /tickets и /cancel доступны владельцу.\n6. Полную переписку можно открыть в админке. Клиент видит только свои обращения. В группе поддержки должны быть только доверенные сотрудники; отвечать через бота может только ADMIN_IDS.\n7. Без группы обращения идут администратору лично. При ошибке прав или доставки смотрите «Чаты → Ошибки доставки». Исправьте права, затем повторите отправку. Старые сообщения общего чата остаются в нём; новые идут по темам.'),
    'history': ('История и уведомления', 'Создайте отдельную закрытую группу, добавьте бота и выполните /bind_history. Эта группа предназначена для событий, переписка клиентов идёт в темы поддержки.\n\n«История событий → Фильтр уведомлений» выбирает категории. По умолчанию включены регистрации, платные подписки, покупки и выплаты. Пробные активации, ответы в тикетах, ключи и бонусы выключены, чтобы избежать шума. Полный журнал остаётся доступным в админке.\n\nВключение категории не рассылает старые исключённые события. Финансовые статусы проверяются каждую минуту и учитывают только подтверждённые записи. История не содержит банковских реквизитов и текстов обращений. При отсутствии группы события сохраняются в базе.'),
    'clients': ('Клиенты и поиск', 'Откройте «Клиенты» или «Поиск». Поиск принимает Telegram ID, username либо часть имени. Карточка показывает регистрацию, баланс, покупки, подписки и ключи. «Связаться» открывает профиль по ID; возможность переписки зависит от настроек Telegram клиента.\n\n«Выдать ключ» позволяет создать тестовую запись либо перенести существующий ключ. Проверьте владельца перед подтверждением: ключ исчезнет у прежнего клиента. Удаление доступно в карточке ключа. Реальные VPN-конфигурации будут доступны после подключения сервера.\n\n«Подписки» позволяет продлить срок в днях. Продление отсчитывается от текущего окончания либо от текущего времени, если срок уже истёк. Блокировка ограничивает клиентскую часть бота; администратора блокировать нельзя.'),
    'tariffs': ('Тарифы и пробный период', 'В «Тарифы» выберите тариф: меняются название, цена в рублях, лимит устройств и доступность продажи. Описание редактируется через «Управление → Инструкции». Изменение цены не меняет сумму старых платежей.\n\nВ «Пробный период» задайте часы: 24 — сутки, 168 — неделя. Изменения действуют только для новых активаций. Бесплатный пробный период выдаётся один раз клиенту. Лимит устройств сейчас хранится как настройка, реальное ограничение требует VPN-интеграции.\n\nНазвания конкретных подписок клиент меняет в карточке подписки: например «Мама» или «Мой телефон». Не путайте это с названием тарифного предложения.'),
    'appearance': ('Оформление и контент', 'Все визуальные настройки собраны в «Оформление». В «Экраны» выберите раздел и отправьте фотографию, GIF-анимацию или видео; новое медиа заменяет предыдущее, символ — удаляет его. «Вступление» добавляет текст перед автоматически рассчитанными ценами, сроками и балансом. Короткий текст используется как подпись, длинный отправляется рядом отдельным сообщением.\n\n«Кнопки» меняют подпись, кастомную Telegram-иконку и цвет. Переход кнопки сохраняется. «Тексты» меняют приветствие, бренд и ссылку поддержки. Описания тарифов, инструкции, FAQ и документы находятся в «Управление → Инструкции». Перед рассылкой проверьте результат со стороны обычного клиента.'),
    'campaigns': ('Рассылки', 'Выберите «Управление → Рассылки» и группу: все, с активной незамороженной подпиской, без активной подписки. Заблокированные пользователи исключены.\n\nПришлите текст или фото с подписью. Проверьте предпросмотр и количество получателей, затем подтвердите отправку. Без подтверждения рассылка не начинается. Состав группы определяется при подтверждении.\n\nИстория рассылок показывает доставленные сообщения, ошибки и очередь. «Отменить» останавливает неотправленные сообщения, уже начатое может успеть уйти. Очередь сохраняется после рестарта. Возможен повтор при аварии между отправкой и фиксацией результата. Реальные рассылки не используйте для проверки — сначала просмотрите черновик.'),
    'sales': ('Отчёты и финансы', 'В «Продажи» выберите неделю, месяц или всё время. Отчёт показывает новых клиентов, выданные подписки, активных клиентов, покупателей, оплаченные суммы, средний платёж, возвраты и продажи по тарифам.\n\n«Добавить расход» принимает сумма в рублях | описание. Результат до налогов: оплаченные суммы минус возвраты, внесённые расходы и бонусы. Выплаты с баланса показываются отдельно, чтобы не вычитать бонус дважды.\n\nCSV выгружает платежи с клиентом, подпиской, статусом и суммой. Период по дате создания UTC, выплаты — по обработке; названия тарифов текущие. Реальные подключения VPN пока не измеряются. Это управленческий расчёт по данным базы, а не бухгалтерский отчёт.'),
    'referrals': ('Рефералы и вывод', 'В «Рефералы» задайте процент и минимальную покупку. В «Правила» выберите первую либо каждую покупку и фиксированный бонус: 0 означает процент; фиксированная сумма не выше покупки. Бонус начисляется один раз для подтверждённого платежа, при полном возврате сторнируется.\n\nКлиент создаёт заявку на доступный баланс, указывает банк, карту или телефон и ФИО. После подтверждения сумма резервируется. Доступны минимальная сумма и выключение заявок.\n\nВ «Выплаты» проверьте реквизиты, выполните банковский перевод вручную и только потом отметьте «Уже выплачено». Бот сам деньги не переводит. Отклонение возвращает резерв однократно. Реквизиты зашифрованы; храните защищённую копию ENCRYPTION_KEY вместе с резервной копией базы.'),
    'reminders': ('Напоминания', 'Откройте «Управление → Напоминания». Включите отправку и задайте число часов до окончания: 72 — три дня. Для пробных подписок есть отдельный переключатель.\n\nПроверка раз в минуту. На данный срок окончания отправляется одно напоминание; замороженные подписки исключены. Продление делает старое уведомление неактуальным. Клиент может отключить напоминания в помощи. После рестарта бот также учитывает подписки, уже вошедшие в заданное окно.'),
    'proxy': ('Пошаговое подключение Telemt', 'Шаг 1. Установите актуальный Telemt на отдельном сервере и настройте рабочий MTProxy-порт для клиентов.\n\nШаг 2. В конфигурации Telemt включите [server.api], задайте длинный случайный auth_header, runtime_edge_enabled = true, public_host и public_port. auth_header — это код управления сервером для бота, а не клиентский secret.\n\nШаг 3. В firewall разрешите API только IP сервера бота 45.80.231.168/32. Если API идёт через интернет, настройте HTTPS. Для приватной сети или WireGuard можно использовать приватный HTTP-адрес.\n\nШаг 4. В боте нажмите «Подключить сервер Telemt». Мастер по очереди запросит название, API URL, группу, приоритет, лимит IP, лимит TCP и auth_header. Секретное сообщение удаляется после обработки. Для быстрого повторного ввода поддерживается одна строка через |.\n\nШаг 5. Выберите группу: vpn — бесплатно с VPN; paid — отдельная покупка; all — обе категории. Чем меньше приоритет, тем выше сервер в списке.\n\nПосле этого бот проверит API. При выборе сервера клиентом бот создаст пользователя freeman_ID, получит уникальный secret и установит срок и лимиты. Карточка сервера покажет доступность, пользователей, соединения и трафик. Несколько серверов станут основным и резервными; резервный клиент выбирает вручную. Authorization хранится зашифрованно.'),
    'vpn': ('Подключение VPN-серверов', 'Для автоматической выдачи используется Amnezia API, установленный на каждом VPN-сервере. Поддерживаются AmneziaWG, AmneziaWG 3.1 и Xray.\n\n1. Сначала установите VPN на сервер через приложение AmneziaVPN. Для новых узлов рекомендуется AmneziaWG 3.1.\n2. На том же сервере установите Amnezia API: git clone https://github.com/kyoresuas/amnezia-api.git, затем cd amnezia-api и bash ./scripts/setup.sh. Установщик найдёт контейнеры Amnezia и создаст FASTIFY_API_KEY.\n3. Настройте HTTPS. Разрешите доступ к API только с IP бота 45.80.231.168/32. Не публикуйте API-ключ и закройте /docs и /metrics на внешнем интерфейсе.\n4. В боте откройте Администратор → Дополнительно → VPN-серверы → Подключить VPN-сервер. Мастер запросит название, страну, HTTPS URL, протокол, приоритет, лимит клиентов и FASTIFY_API_KEY.\n5. Добавьте столько стран и серверов, сколько требуется. Бот показывает доступность, нагрузку, число клиентов, онлайн и трафик. Клиент выбирает страну после покупки; бот создаёт персональный ключ со сроком подписки. При смене страны старая конфигурация отзывается.\n\nAPI-ключ хранится зашифрованно. Если узел недоступен или заполнен, он не показывается новым клиентам. Перед запуском продаж проверьте создание, удаление и импорт ключа на тестовом аккаунте.'),
    'monitoring': ('Мониторинг и резервные копии', 'Хост проверяет бота, базу данных, контейнер, свободное место и таймер локальных копий каждые пять минут. Владелец получает уведомление только при переходе в состояние сбоя и после восстановления.\n\nSQLite ежедневно копируется средствами SQLite Backup API, проходит integrity_check и хранится на VPS семь дней. Дополнительно бот раз в сутки отправляет владельцу зашифрованную копию. Эту отправку можно отключить в панели. Файл имеет расширение .fernet; для расшифровки нужен ENCRYPTION_KEY из .env. Храните ключ отдельно от сервера.'),
    'roles': ('Роли сотрудников', 'Владелец вводит Telegram ID сотрудника и роль через вертикальную черту: 123456789 | support или 123456789 | manager.\n\nПоддержка видит тикеты и историю обращений. Менеджер видит клиентов, покупки, продажи, отчёты и воронку. Цены, ключи, выплаты, рассылки, прокси и системные настройки доступны только владельцу. Роль можно удалить в карточке сотрудника. Бесплатная покупка подписки также доступна только владельцу.'),
    'prices': ('Персональные цены клиента', 'Откройте Клиенты → карточка клиента → Скидка и специальные цены. Постоянная скидка задаётся в процентах 0–100; 0 отменяет её. Для каждого тарифа можно назначить цену в рублях, ввод - отменяет специальную цену. Специальная цена имеет приоритет; иначе применяется большая из постоянной скидки и промокода. Скидки не складываются. Изменения сохраняются в базе и журнале.'),
    'home': ('Как пользоваться админкой', 'Админка доступна только Telegram ID из ADMIN_IDS. Клиент видит свою часть бота.\n\nВыберите раздел справки ниже. Отдельные инструкции объясняют поддержку с темами, события, клиентов, тарифы, оформление, рассылки, финансы, рефералов и напоминания.\n\nДействия с подтверждением проверяйте по клиенту, сумме и сроку. /cancel отменяет ввод, /admin возвращает панель. Изменения настроек сохраняются в базе. Платёжная и VPN-интеграции пока не подключены. Резервные копии базы создаются ежедневно на том же VPS; внешняя копия базы и .env остаётся необходима для восстановления при потере сервера.')
}


GUIDES['gifts']=('Подарить другу', 'В карточке подписки после оформления доступна кнопка Подарить другу. Все кнопки находятся под сообщением; обычная клавиатура не используется.\n\nВыбрать пользователя открывает выбор чата Telegram и отправку обычной ссылки-приглашения. Когда друг открывает её, отправитель получает запрос с именем, username и Telegram ID. Отправитель подтверждает получателя, после чего друг получает кнопку активации. До подтверждения ключ не резервируется и оплата не списывается. Проверяйте ID: ссылку могут переслать, но подарок получит только подтверждённый вами пользователь. Открытое приглашение действительно три дня.\n\nВвести username или ID позволяет указать получателя вручную. Username должен быть известен боту; числовой ID может принадлежать новому пользователю. Затем подтвердите подарок и отправьте приглашение.\n\nКопировать приглашение копирует именно ссылку на активацию без текста и параметров отправки. При получении старый ключ отзывается и создаётся новый на оставшийся срок. Неполученный подарок можно отменить. Сейчас ключи тестовые.')


