def guide(section='home'):
    if section not in GUIDES:
        section='home'
    title,text=GUIDES[section]
    rows=[[(label,f'admin:guide:{key}')] for key,(label,_) in GUIDES.items() if key!='home'] if section=='home' else [[('📖 Все инструкции','admin:guide:home')]]
    return Screen(f'📖 <b>{title}</b>\n\n{text}',rows+[[('← Назад','admin:home')]])
